<script>(()=>{const nav=document.querySelector('[data-e801-nav]');document.querySelector('[data-e801-menu-toggle]')?.addEventListener('click',()=>nav?.classList.toggle('is-open'));document.querySelectorAll('[data-e801-slider]').forEach(slider=>{const slides=[...slider.querySelectorAll('[data-e801-slide]')];if(slides.length<2)return;let i=0;const show=n=>{slides[i].classList.remove('is-active');i=(n+slides.length)%slides.length;slides[i].classList.add('is-active')};slider.querySelector('[data-e801-prev]')?.addEventListener('click',()=>show(i-1));slider.querySelector('[data-e801-next]')?.addEventListener('click',()=>show(i+1));setInterval(()=>show(i+1),Math.max(3500,Number(slider.dataset.autoplay||6500)))})})();</script>
